package com.coffeeshop.repository;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.DocumentModels;import javax.sql.DataSource;import java.sql.*;import java.util.*;public final class JdbcDocumentRepository implements DocumentRepository{private final DataSource ds;public JdbcDocumentRepository(DataSource d){ds=Objects.requireNonNull(d);}public DocumentModels.Catalog load(){try(Connection c=ds.getConnection()){return new DocumentModels.Catalog(orders(c),documents(c));}catch(SQLException e){throw fail("Unable to load receipts and invoices.",e);}}private List<DocumentModels.Order>orders(Connection c)throws SQLException{String q="SELECT o.order_id,o.order_number,COALESCE(NULLIF(c.legal_name,''),NULLIF(LTRIM(RTRIM(CONCAT(c.first_name,' ',c.last_name))),''),'Walk-in'),o.completed_at,o.total_amount FROM dbo.orders o LEFT JOIN dbo.customers c ON c.customer_id=o.customer_id WHERE o.status='COMPLETED' ORDER BY o.completed_at DESC";try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<DocumentModels.Order>x=new ArrayList<>();while(r.next())x.add(new DocumentModels.Order(r.getLong(1),r.getString(2),r.getString(3),r.getTimestamp(4).toLocalDateTime(),r.getBigDecimal(5)));return x;}}private List<DocumentModels.Document>documents(Connection c)throws SQLException{String q="SELECT r.receipt_id,r.order_id,o.order_number,r.document_number,r.document_type,r.issued_at,u.username,r.subtotal_amount,r.discount_amount,r.tax_amount,r.total_amount,r.customer_name_snapshot,r.business_name_snapshot,r.tax_registration_number_snapshot,r.billing_address_snapshot FROM dbo.receipts r JOIN dbo.orders o ON o.order_id=r.order_id JOIN dbo.users u ON u.user_id=r.issued_by_user_id ORDER BY r.issued_at DESC";try(PreparedStatement s=c.prepareStatement(q);ResultSet r=s.executeQuery()){List<DocumentModels.Document>x=new ArrayList<>();while(r.next())x.add(new DocumentModels.Document(r.getLong(1),r.getLong(2),r.getString(3),r.getString(4),r.getString(5),r.getTimestamp(6).toLocalDateTime(),r.getString(7),r.getBigDecimal(8),r.getBigDecimal(9),r.getBigDecimal(10),r.getBigDecimal(11),r.getString(12),r.getString(13),r.getString(14),r.getString(15)));return x;}}public long issue(long orderId,String type,long user){try(Connection c=ds.getConnection()){c.setAutoCommit(false);c.setTransactionIsolation(Connection.TRANSACTION_SERIALIZABLE);try{String q="SELECT o.subtotal_amount,o.discount_amount,o.tax_amount,o.total_amount,c.first_name,c.last_name,c.legal_name,c.tax_registration_number,(SELECT TOP(1) CONCAT(a.address_line1,CASE WHEN a.address_line2 IS NULL THEN '' ELSE CONCAT(', ',a.address_line2) END,', ',a.city,CASE WHEN a.region IS NULL THEN '' ELSE CONCAT(', ',a.region) END,CASE WHEN a.postal_code IS NULL THEN '' ELSE CONCAT(' ',a.postal_code) END) FROM dbo.customer_addresses a WHERE a.customer_id=c.customer_id AND a.is_active=1 ORDER BY a.is_default DESC,a.customer_address_id) FROM dbo.orders o WITH(UPDLOCK,HOLDLOCK) LEFT JOIN dbo.customers c ON c.customer_id=o.customer_id WHERE o.order_id=? AND o.status='COMPLETED'";try(PreparedStatement s=c.prepareStatement(q)){s.setLong(1,orderId);try(ResultSet r=s.executeQuery()){if(!r.next())throw new IllegalStateException("The order is not completed or no longer exists.");String customer=r.getString(5)==null?null:(r.getString(5)+" "+Objects.toString(r.getString(6),"")).trim();try(PreparedStatement i=c.prepareStatement("INSERT dbo.receipts(order_id,document_number,document_type,issued_by_user_id,subtotal_amount,discount_amount,tax_amount,total_amount,customer_name_snapshot,business_name_snapshot,tax_registration_number_snapshot,billing_address_snapshot) VALUES(?,CONCAT((SELECT setting_value FROM dbo.settings WHERE setting_key='numbering.document.prefix'),FORMAT(NEXT VALUE FOR dbo.seq_document_number,'00000000')),?,?,?,?,?,?,?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){i.setLong(1,orderId);i.setString(2,type);i.setLong(3,user);i.setBigDecimal(4,r.getBigDecimal(1));i.setBigDecimal(5,r.getBigDecimal(2));i.setBigDecimal(6,r.getBigDecimal(3));i.setBigDecimal(7,r.getBigDecimal(4));nullable(i,8,customer);nullable(i,9,r.getString(7));nullable(i,10,r.getString(8));nullable(i,11,r.getString(9));i.executeUpdate();long id=key(i);c.commit();return id;}}}}catch(Exception e){c.rollback();throw e;}}catch(RuntimeException e){throw e;}catch(Exception e){throw fail("Unable to issue document.",e);}}private static void nullable(PreparedStatement s,int i,String v)throws SQLException{if(v==null||v.isBlank())s.setNull(i,Types.NVARCHAR);else s.setString(i,v);}private static long key(PreparedStatement s)throws SQLException{try(ResultSet r=s.getGeneratedKeys()){if(!r.next())throw new SQLException("Generated key unavailable");return r.getLong(1);}}private static DatabaseException fail(String m,Exception e){return new DatabaseException(m,e);}}
